<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><div class="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4"><div><h1 class="h3 mb-1">File Saya</h1><p class="text-secondary mb-0">Kelola file pribadi Anda.</p></div><form action="/files/upload" method="post" enctype="multipart/form-data" class="d-flex gap-2"><?= csrf_field() ?><input class="form-control" type="file" name="file" required><button class="btn btn-primary">Upload</button></form></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Nama file</th><th>Tipe</th><th>Ukuran</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach($files as $f): ?><tr><td><?= esc($f['original_name']) ?></td><td><?= esc($f['mime_type']) ?></td><td><?= number_format($f['size_bytes']/1048576,2) ?> MB</td><td><?= esc($f['created_at']) ?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="/files/download/<?= (int)$f['id'] ?>">Download</a><form method="post" action="/files/delete/<?= (int)$f['id'] ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Pindahkan file ke sampah?')">Hapus</button></form></td></tr><?php endforeach ?><?php if(!$files): ?><tr><td colspan="5" class="text-center text-secondary py-4">Belum ada file.</td></tr><?php endif ?></tbody></table></div></div><?= $this->endSection() ?>
